arguments.command:
cd /tmp/sv-8368e17d34c1468badceb609f2410d01/symbols && \
# Use llvm tools to get dynamic symbols and find what's at the given offsets
# Offsets for libmonosgen-2.0.so: 0x222098, 0x222234, 0x19bac0, 0x19bc14
echo "=== Dynamic symbols near offsets in libmonosgen-2.0.so ===" && \
llvm-nm-16 --dynamic libmonosgen-2.0.so 2>/dev/null | sort | awk '
BEGIN { 
  targets[1] = 0x222098; targets[2] = 0x222234; targets[3] = 0x19bac0; targets[4] = 0x19bc14
}
{ 
  addr = strtonum("0x" $1)
  for (i in targets) {
    if (addr <= targets[i] && addr > best_addr[i]) {
      best_addr[i] = addr
      best_sym[i] = $3
    }
  }
}
END {
  for (i in targets) {
    printf "0x%x -> %s+0x%x\n", targets[i], best_sym[i], targets[i] - best_addr[i]
  }
}' | sort

