arguments.command:
cd /tmp/sv-8368e17d34c1468badceb609f2410d01/symbols && \
# Get sorted dynamic symbols and find closest match for each offset
llvm-nm-16 --dynamic --defined-only libmonosgen-2.0.so 2>/dev/null | sort > mono_syms.txt && \
for offset in 0x222098 0x222234 0x19bac0 0x19bc14; do
  # Find the largest symbol address <= offset
  result=$(awk -v target="$offset" '
  BEGIN { target_dec = strtonum(target); best_addr = 0; best_sym = "" }
  /^[0-9a-f]/ {
    addr = strtonum("0x" $1)
    if (addr <= target_dec && addr > best_addr) {
      best_addr = addr
      best_sym = $3
    }
  }
  END { printf "%s+0x%x\n", best_sym, target_dec - best_addr }
  ' mono_syms.txt)
  echo "  $offset -> $result"
done

